using System.Text.Json;
using Dapper;
using Sigov.Application.Operational;
using Sigov.Infrastructure.Persistence.Dapper;

namespace Sigov.Infrastructure.Operational;

public sealed class KanbanRepository : IKanbanRepository { private readonly DapperContext _context; public KanbanRepository(DapperContext context)=>_context=context; public async Task<IReadOnlyList<KanbanCardDto>> ListarAsync(long tenantId,string origem,long? responsavelId,string? sla,CancellationToken cancellationToken){using var connection=_context.CreateConnection(); var rows=await connection.QueryAsync<KanbanCardDto>(new CommandDefinition(@"select id, tenant_id as TenantId, origem, entidade_id as EntidadeId, titulo, coluna, ordem, responsavel_id as ResponsavelId, prazo_em as PrazoEm from sigov.kanban_card where tenant_id = @TenantId and origem = @Origem and (@ResponsavelId is null or responsavel_id = @ResponsavelId) and (@Sla is null or sla = @Sla) and is_deleted = false order by coluna, ordem, id;", new {TenantId=tenantId, Origem=origem, ResponsavelId=responsavelId, Sla=sla}, cancellationToken:cancellationToken)).ConfigureAwait(false); return rows.AsList();} public async Task MoverAsync(long tenantId,long cardId,string coluna,int ordem,OperationalCommandContext context,CancellationToken cancellationToken){using var connection=_context.CreateConnection(); await connection.ExecuteAsync(new CommandDefinition(@"update sigov.kanban_card set coluna = @Coluna, ordem = @Ordem, updated_at = now(), updated_by = @UserId, correlation_id = @CorrelationId where tenant_id = @TenantId and id = @CardId and is_deleted = false; insert into sigov.kanban_historico (tenant_id, card_id, acao, depois_json, created_by, correlation_id) values (@TenantId, @CardId, 'kanban.status.alterado', jsonb_build_object('coluna', @Coluna, 'ordem', @Ordem), @UserId, @CorrelationId);", new {TenantId=tenantId, CardId=cardId, Coluna=coluna, Ordem=ordem, context.UserId, context.CorrelationId}, cancellationToken:cancellationToken)).ConfigureAwait(false);} }
